ublic.persons FOR EACH ROW EXECUTE FUNCTION update_persons_updated_at()"},{"name":"trigger_students_updated_at","function":"update_students_updated_at()","relation":"students","definition":"CREATE TRIGGER trigger_students_updated_at BEFORE UPDATE ON public.students FOR EACH ROW EXECUTE FUNCTION update_students_updated_at()"},{"name":"audit_tenants_changes","function":"log_audit_event()","relation":"tenants","definition":"CREATE TRIGGER audit_tenants_changes AFTER INSERT OR DELETE OR UPDATE ON public.tenants FOR EACH ROW EXECUTE FUNCTION log_audit_event()"},{"name":"update_tenants_updated_at","function":"update_updated_at_column()","relation":"tenants","definition":"CREATE TRIGGER update_tenants_updated_at BEFORE UPDATE ON public.tenants FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()"},{"name":"audit_users_changes","function":"log_audit_event()","relation":"users","definition":"CREATE TRIGGER audit_users_changes AFTER INSERT OR DELETE OR UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION log_audit_event()"},{"name":"tr_sync_user_claims","function":"sync_user_claims_to_auth()","relation":"users","definition":"CREATE TRIGGER tr_sync_user_claims AFTER INSERT OR UPDATE OF role, tenant_id ON public.users FOR EACH ROW EXECUTE FUNCTION sync_user_claims_to_auth()"},{"name":"update_users_updated_at","function":"update_updated_at_column()","relation":"users","definition":"CREATE TRIGGER update_users_updated_at BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()"}],"functions":[{"acl":"{=X/postgres,bella_migration_executor=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"8cb9c457e4d4d71b5d56df6ed01ceefb","owner":"postgres","config":null,"definer":true,"signature":"current_tenant_id()","definition":"CREATE OR REPLACE FUNCTION public.current_tenant_id()\n RETURNS uuid\n LANGUAGE sql\n STABLE SECURITY DEFINER\nAS $function$\n  SELECT tenant_id FROM public.users WHERE id = auth.uid();\n$function$\n"},{"acl":"{=X/postgres,bella_migration_executor=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"365d8ec3a2e5a7c787ca4129e2550d55","owner":"postgres","config":null,"definer":true,"signature":"current_user_role()","definition":"CREATE OR REPLACE FUNCTION public.current_user_role()\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\nAS $function$\n  SELECT role FROM public.users WHERE id = auth.uid();\n$function$\n"},{"acl":"{authenticated=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"0bd77a772ef098df2f09ba02bd58ec5e","owner":"postgres","config":["search_path=public"],"definer":true,"signature":"edu_set_daily_attendance(uuid,uuid,text,timestamp with time zone,date)","definition":"CREATE OR REPLACE FUNCTION public.edu_set_daily_attendance(p_tenant_id uuid, p_enrollment_id uuid, p_status text, p_roll_call_time timestamp with time zone, p_school_day date)\n RETURNS TABLE(id uuid, tenant_id uuid, enrollment_id uuid, school_day date, status text, event_id uuid, roll_call_time timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_enrollment_id UUID;\r\n  v_event_id UUID;\r\n  v_state public.edu_attendance_daily_state%ROWTYPE;\r\nBEGIN\r\n  IF p_status NOT IN ('present', 'absent', 'excused') THEN\r\n    RAISE EXCEPTION 'INVALID_ATTENDANCE_STATUS: %', p_status USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF p_roll_call_time IS NULL THEN\r\n    RAISE EXCEPTION 'ROLL_CALL_TIME_REQUIRED' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  IF p_school_day IS NULL THEN\r\n    RAISE EXCEPTION 'SCHOOL_DAY_REQUIRED' USING ERRCODE = '22023';\r\n  END IF;\r\n\r\n  SELECT e.id\r\n  INTO v_enrollment_id\r\n  FROM public.edu_enrollments e\r\n  WHERE e.id = p_enrollment_id\r\n    AND e.tenant_id = p_tenant_id;\r\n\r\n  IF v_enrollment_id IS NULL THEN\r\n    RAISE EXCEPTION 'Enrollment % not found for tenant %', p_enrollment_id, p_tenant_id\r\n      USING ERRCODE = 'P0002';\r\n  END IF;\r\n\r\n  INSERT INTO public.edu_attendance (\r\n    tenant_id,\r\n    enrollment_id,\r\n    status,\r\n    roll_call_time\r\n  )\r\n  VALUES (\r\n    p_tenant_id,\r\n    p_enrollment_id,\r\n    p_status,\r\n    p_roll_call_time\r\n  )\r\n  RETURNING edu_attendance.id INTO v_event_id;\r\n\r\n  INSERT INTO public.edu_attendance_daily_state (\r\n    tenant_id,\r\n    enrollment_id,\r\n    school_day,\r\n    status\r\n  )\r\n  VALUES (\r\n    p_tenant_id,\r\n    p_enrollment_id,\r\n    p_school_day,\r\n    p_status\r\n  )\r\n  ON CONFLICT ON CONSTRAINT edu_attendance_daily_state_unique\r\n  DO UPDATE SET\r\n    status = EXCLUDED.status,\r\n    updated_at = now()\r\n  RETURNING * INTO v_state;\r\n\r\n  RETURN QUERY SELECT\r\n    v_state.id AS id,\r\n    v_state.tenant_id AS tenant_id,\r\n    v_state.enrollment_id AS enrollment_id,\r\n    v_state.school_day AS school_day,\r\n    v_state.status AS status,\r\n    v_event_id AS event_id,\r\n    p_roll_call_time AS roll_call_time,\r\n    v_state.created_at AS created_at,\r\n    v_state.updated_at AS updated_at;\r\nEND;\r\n$function$\n"},{"acl":"{=X/postgres,bella_migration_executor=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"cceebaaeaf39cd21640880d0fbdb8963","owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"signature":"get_auth_tenant_id()","definition":"CREATE OR REPLACE FUNCTION public.get_auth_tenant_id()\n RETURNS uuid\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n  v_tenant_id uuid;\nBEGIN\n  SELECT u.tenant_id INTO v_tenant_id\n  FROM public.users AS u\n  JOIN public.tenants AS t ON t.id = u.tenant_id\n  WHERE u.id = auth.uid() AND u.status = 'active' AND t.status = 'active';\n\n  -- NULL would enable legacy policies using NULL as an unrestricted HQ sentinel.\n  IF v_tenant_id IS NULL THEN\n    RAISE EXCEPTION 'Active canonical identity and tenant required' USING ERRCODE = '42501';\n  END IF;\n  RETURN v_tenant_id;\nEND;\n$function$\n"},{"acl":"{=X/postgres,bella_migration_executor=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"beead9fad3f0d80f0a7580b32c104bce","owner":"postgres","config":null,"definer":true,"signature":"log_audit_event()","definition":"CREATE OR REPLACE FUNCTION public.log_audit_event()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    current_user_id UUID;\n    record_tenant_id UUID;\nBEGIN\n    BEGIN\n        current_user_id := auth.uid();\n    EXCEPTION WHEN OTHERS THEN\n        current_user_id := NULL;\n    END;\n    \n    BEGIN\n        IF TG_TABLE_NAME = 'tenants' THEN\n            IF TG_OP = 'DELETE' THEN\n                record_tenant_id := OLD.id;\n            ELSE\n                record_tenant_id := NEW.id;\n            END IF;\n        ELSE\n            IF TG_OP = 'DELETE' THEN\n                record_tenant_id := OLD.tenant_id;\n            ELSE\n                record_tenant_id := NEW.tenant_id;\n            END IF;\n        END IF;\n    EXCEPTION WHEN OTHERS THEN\n        record_tenant_id := NULL;\n    END;\n\n    BEGIN\n        INSERT INTO public.audit_logs (\n            tenant_id,\n            table_name,\n            record_id,\n            action,\n            old_data,\n            new_data,\n            changed_by_id\n        ) VALUES (\n            record_tenant_id,\n            TG_TABLE_NAME,\n            COALESCE(NEW.id, OLD.id),\n            TG_OP,\n            CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD)::jsonb ELSE NULL END,\n            CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW)::jsonb ELSE NULL END,\n            current_user_id\n        );\n    EXCEPTION WHEN OTHERS THEN\n        RAISE WARNING 'audit_log_event failed for table % op %: %', TG_TABLE_NAME, TG_OP, SQLERRM;\n    END;\n\n    IF TG_OP = 'DELETE' THEN\n        RETURN OLD;\n    ELSE\n        RETURN NEW;\n    END IF;\nEND;\n$function$\n"},{"acl":"{=X/postgres,bella_migration_executor=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"db91de20032102a61925397077249451","owner":"postgres","config":null,"definer":true,"signature":"sync_user_claims_to_auth()","definition":"CREATE OR REPLACE FUNCTION public.sync_user_claims_to_auth()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  UPDATE auth.users\n  SET raw_app_meta_data = \n    coalesce(raw_app_meta_data, '{}'::jsonb) || \n    jsonb_build_object(\n      'role', NEW.role,\n      'tenant_id', NEW.tenant_id\n    )\n  WHERE id = NEW.id;\n  RETURN NEW;\nEND;\n$function$\n"}],"relations":[{"acl":"{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"audit_logs","owner":"postgres","forceRls":false,"definition":null},{"acl":"{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"edu_attendance","owner":"postgres","forceRls":false,"definition":null},{"acl":"{bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"edu_attendance_daily_state","owner":"postgres","forceRls":false,"definition":null},{"acl":"{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"edu_courses","owner":"postgres","forceRls":false,"definition":null},{"acl":"{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,bella_d