postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"party_relationships","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=arwdDxtm/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"people_directory","owner":"postgres","forceRls":false,"definition":null},{"acl":"{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"persons","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=arwdDxtm/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"students","owner":"postgres","forceRls":false,"definition":null},{"acl":"{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"tenants","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=r/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":false,"kind":"v","name":"user_org_unit_access","owner":"postgres","forceRls":false,"definition":" WITH RECURSIVE current_context AS (\n         SELECT COALESCE(auth.uid(), NULLIF(current_setting('app.current_user_id'::text, true), ''::text)::uuid) AS user_id,\n            COALESCE(get_auth_tenant_id(), NULLIF(current_setting('app.current_tenant_id'::text, true), ''::text)::uuid) AS tenant_id\n        ), direct_access AS (\n         SELECT pd.user_id,\n            rel.tenant_id,\n            rel.to_id AS org_unit_id,\n            rel.to_id AS root_org_unit_id,\n            rel.id AS relationship_id,\n            rel.rel_type AS access_source\n           FROM current_context ctx\n             JOIN people_directory pd ON pd.user_id = ctx.user_id AND pd.tenant_id = ctx.tenant_id AND pd.is_active = true\n             JOIN org_relationships rel ON rel.tenant_id = pd.tenant_id AND rel.from_id = pd.id AND rel.from_type = 'person'::text AND rel.to_type = 'unit'::text AND (rel.rel_type = ANY (ARRAY['belongs_to'::text, 'manages'::text, 'participates_in'::text])) AND (rel.since IS NULL OR rel.since <= CURRENT_DATE) AND (rel.until IS NULL OR rel.until >= CURRENT_DATE)\n             JOIN org_units ou ON ou.id = rel.to_id AND ou.tenant_id = rel.tenant_id AND ou.is_active = true\n        ), expanded_access AS (\n         SELECT direct_access.user_id,\n            direct_access.tenant_id,\n            direct_access.org_unit_id,\n            direct_access.root_org_unit_id,\n            direct_access.relationship_id,\n            direct_access.access_source\n           FROM direct_access\n        UNION\n         SELECT ea.user_id,\n            child.tenant_id,\n            child.id AS org_unit_id,\n            ea.root_org_unit_id,\n            ea.relationship_id,\n            ea.access_source\n           FROM expanded_access ea\n             JOIN org_units child ON child.parent_id = ea.org_unit_id AND child.tenant_id = ea.tenant_id AND child.is_active = true\n        ), admin_access AS (\n         SELECT u.id AS user_id,\n            ou.tenant_id,\n            ou.id AS org_unit_id,\n            ou.id AS root_org_unit_id,\n            NULL::uuid AS relationship_id,\n            'tenant_admin'::text AS access_source\n           FROM current_context ctx\n             JOIN users u ON u.id = ctx.user_id AND u.tenant_id = ctx.tenant_id AND (lower(u.role) = ANY (ARRAY['admin'::text, 'super_admin'::text]))\n             JOIN org_units ou ON ou.tenant_id = u.tenant_id AND ou.is_active = true\n        )\n SELECT DISTINCT expanded_access.user_id,\n    expanded_access.tenant_id,\n    expanded_access.org_unit_id,\n    expanded_access.root_org_unit_id,\n    expanded_access.relationship_id,\n    expanded_access.access_source\n   FROM expanded_access\nUNION\n SELECT DISTINCT admin_access.user_id,\n    admin_access.tenant_id,\n    admin_access.org_unit_id,\n    admin_access.root_org_unit_id,\n    admin_access.relationship_id,\n    admin_access.access_source\n   FROM admin_access;"},{"acl":"{anon=r/postgres,authenticated=r/postgres,bella_developer=r/postgres,bella_migration_executor=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,verification_executor=r/postgres}","rls":true,"kind":"r","name":"users","owner":"postgres","forceRls":false,"definition":null}],"constraints":[{"name":"audit_logs_action_check","relation":"audit_logs","definition":"CHECK (action = ANY (ARRAY['INSERT'::text, 'UPDATE'::text, 'DELETE'::text]))"},{"name":"audit_logs_changed_by_id_fkey","relation":"audit_logs","definition":"FOREIGN KEY (changed_by_id) REFERENCES users(id) ON DELETE SET NULL"},{"name":"audit_logs_pkey","relation":"audit_logs","definition":"PRIMARY KEY (id)"},{"name":"audit_logs_tenant_id_fkey","relation":"audit_logs","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE"},{"name":"edu_attendance_enrollment_id_fkey","relation":"edu_attendance","definition":"FOREIGN KEY (enrollment_id) REFERENCES edu_enrollments(id) ON DELETE RESTRICT"},{"name":"edu_attendance_pkey","relation":"edu_attendance","definition":"PRIMARY KEY (id)"},{"name":"edu_attendance_status_check","relation":"edu_attendance","definition":"CHECK (status = ANY (ARRAY['present'::text, 'absent'::text, 'excused'::text]))"},{"name":"edu_attendance_tenant_id_fkey","relation":"edu_attendance","definition":"FOREI